498   // In Roam, canvas identity is currently keyed by the page UID.
499   // Room sync is graph/page encoded as an opaque base64url token.
500   const pageUid = useMemo(() => getPageUidByPageTitle(title), [title]);
501   const [canvasSyncMode, setCanvasSyncModeState] = useState<CanvasSyncMode>(
502     () => getEffectiveCanvasSyncMode({ pageUid }),
503   );
504 
505   const useCloudflareSync =
506     canvasSyncMode === "sync" && !!TLDRAW_CLOUDFLARE_SYNC_WS_BASE_URL;
507 
508   useEffect(() => {
509     setCanvasSyncModeState(ensureCanvasSyncMode({ pageUid }));
510   }, [pageUid]);
511 
512   // Convert from local to sync when the block props change
513   // EG: When UserA sets the canvas sync mode to sync
514   // UserB's canvas should be converted to sync
515   useEffect(() => {
516     if (!pageUid || canvasSyncMode !== "local") return;
517 
518     const pullWatchProps = [
519       "[:block/props]",
520       `[:block/uid "${pageUid}"]`,
521       (_before: PullBlock | null, after: PullBlock | null) => {
522         const blockProps = normalizeProps(
523           (after?.[":block/props"] || {}) as json,
524         ) as Record<string, json>;
525         const rjsqb = blockProps?.["roamjs-query-builder"] as Record<
526           string,
527           unknown
528         >;
529         if (rjsqb?.canvasSyncMode !== "sync") return;
530         setCanvasSyncModeState("sync");
531       },
532     ] as const;
533 
534     window.roamAlphaAPI.data.addPullWatch(...pullWatchProps);
535     return () => {
536       window.roamAlphaAPI.data.removePullWatch(...pullWatchProps);
537     };
538   }, [canvasSyncMode, pageUid]);
