540   const onCanvasSyncModeChange = useCallback(
541     (mode: CanvasSyncMode) => {
542       const currentMigrationState = getCanvasSyncMigrationState({ pageUid });
543       const nextMigrationState =
544         mode === "sync" && !currentMigrationState ? "pending" : undefined;
545       setCanvasSyncSettings({
546         pageUid,
547         mode,
548         migrationState: nextMigrationState,
549       });
550       setCanvasSyncModeState(mode);
551     },
552     [pageUid],
553   );
