495 const createEmbedding = async (text: string): Promise<number[]> => {
496   const response = await fetch(`${nextApiRoot()}/embeddings/openai/small`, {
497     method: "POST",
498     headers: { "Content-Type": "application/json" },
499     body: JSON.stringify({ input: text }),
