      "[:find (?e) :in $ ?uid :where [?e :block/uid ?uid]]",
      sourceLocalId,
    );
    if (!result || result.length === 0) return null;
    return sourceLocalId;
  }
  return await findImportedNodeUidBySourceRid(rid);
};
