    expect(login).not.toHaveBeenCalled();
    expect(getBlockProps).not.toHaveBeenCalled();
    expect(setBlockProps).not.toHaveBeenCalled();
  });

  it("does not expose a cached hosted session to a same-name offline graph", async () => {
    activateGraph("hosted");
    await expect(getLoggedInClient()).resolves.toBe(client);

    activateGraph("offline");
    await expect(getSupabaseContext()).resolves.toBeNull();
    await expect(getLoggedInClient()).resolves.toBeNull();
    expect(enroll).toHaveBeenCalledTimes(1);
    expect(login).toHaveBeenCalledTimes(1);
    expect(getSession).not.toHaveBeenCalled();

    activateGraph("hosted", "other-study");
    enroll.mockResolvedValueOnce({ data: { id: 13 } });
    await expect(getSupabaseContext()).resolves.toMatchObject({ spaceId: 13 });
    expect(enroll).toHaveBeenLastCalledWith(
      expect.objectContaining({ name: "other-study" }),
    );
  });

  it("stops enrollment before the next step if the graph switches", async () => {
    activateGraph("hosted");
    const pending = getSupabaseContext();
    activateGraph("offline");

    await expect(pending).resolves.toBeNull();
    expect(enrollAccount).not.toHaveBeenCalled();
  });

  it("retries enrollment after a hosted graph loses connectivity", async () => {
    activateGraph("hosted");
    enroll.mockRejectedValueOnce(new TypeError("Network unavailable"));
    await expect(getSupabaseContext()).resolves.toBeNull();

    await expect(getSupabaseContext()).resolves.toMatchObject({ spaceId: 12 });
    expect(enroll).toHaveBeenCalledTimes(2);
    expect(enrollAccount).toHaveBeenCalledTimes(1);
  });

  it("uses the local canvas when the offline copy retains cloud settings", () => {
    const page = { pageUid: "canvas" };
    getBlockProps.mockReturnValue({
      "roamjs-query-builder": { canvasSyncMode: "sync" },
    });
    activateGraph("hosted");
    expect(getEffectiveCanvasSyncMode(page)).toBe("sync");
    const hostedRoom = getSyncRoomId(page);

    activateGraph("offline");
    expect(getEffectiveCanvasSyncMode(page)).toBe("local");
    expect(ensureCanvasSyncMode(page)).toBe("local");
    expect(() => getSyncRoomId(page)).toThrow("hosted Roam graphs");
    expect(setBlockProps).not.toHaveBeenCalled();

    activateGraph("hosted");
    expect(getSyncRoomId(page)).toBe(hostedRoom);
  });
});

